/* Protótipo de apresentação. Dados fictícios, persistidos somente neste navegador. */
'use strict';
const E=ERP, O=ERP_OFFICIAL, KEY='encantos-erp-demo-v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1)state=E.seed();}catch{state=E.seed();}
if(state.catalogRevision!==O.revision){state=E.applyOfficialCatalog(state);try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
let filter='todos',query='',financeFilter='abertas',currentSlide=0,lastFocus=null,catalogFilter='todos',catalogSearch='';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date=d=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR'):'A combinar';
const short=d=>date(d).slice(0,5);
const customer=id=>state.customers.find(c=>c.id===id);
const product=id=>state.products.find(p=>p.id===id);
const initials=n=>n.split(' ').slice(0,2).map(n=>n[0]).join('');
const paths={mountain:'M2 18 9 5l5 9 3-5 5 9H2Zm5-9 2 3 2-3',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',board:'M3 4h18v16H3zM9 4v16M15 4v16M5 8h2M11 8h2M17 8h2',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',box:'m3 7 9-5 9 5v10l-9 5-9-5V7Zm0 0 9 5 9-5M12 12v10M7.5 4.5l9 5',wallet:'M3 6h17v15H3V6Zm0 0V3h14v3M16 11h5v5h-5z',leaf:'M20 3c-12-2-18 4-14 12s17 3 14-12ZM4 21l12-13',arrow:'M4 12h16m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',down:'m6 9 6 6 6-6',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',alert:'m12 3 10 18H2L12 3Zm0 6v5M12 17v.2',link:'m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 2 1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',close:'m6 6 12 12M6 18 18 6',play:'m8 4 13 8-13 8V4Z',refresh:'M20 7v5h-5M4 17v-5h5M20 12a8 8 0 0 0-14-6M4 12a8 8 0 0 0 14 6',menu:'M3 6h18M3 12h18M3 18h18',chart:'M4 19V5M4 19h17M9 15v-4M14 15V7M19 15v-7',message:'M21 12a9 9 0 0 1-9 9c-2 0-3-.5-4.5-1L3 21l1-4.5A9 9 0 1 1 21 12Z',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2V3Zm4 5h6M9 12h6'};
function icon(name){return `<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.box}"/></svg>`;}
const statuses={novo:['Novo pedido','blue'],analise:['Em análise','amber'],separacao:['Em separação','purple'],pronto:['Pronto','green'],concluido:['Concluído','gray'],cancelado:['Cancelado','red']};
function badge(s){const t=statuses[s]||[s,'gray'];return `<span class="badge ${t[1]}">${t[0]}</span>`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('O navegador não permitiu salvar. Os dados ficam nesta sessão.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function go(route){location.hash='/'+route;}
function route(){return (location.hash.slice(1).split('?')[0]||'/visao-geral').replace(/^\//,'');}
function getOrders(kind){return state.orders.filter(o=>o.status!=='cancelado'&&(!kind||o.kind===kind));}
function pageHeading(kicker,title,sub,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${buttons}</div></div>`;}
function button(text,action,ico='plus',cls='primary',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${icon(ico)}${text}</button>`;}
function metric(title,value,foot,ico){return `<div class="metric"><div class="metric-top">${title}${icon(ico)}</div><div class="metric-value money">${value}</div><div class="metric-foot">${foot}</div></div>`;}
const nav=[['visao-geral','grid','Visão geral'],['catalogo','leaf','Catálogo oficial'],['pedidos','board','Pedidos'],['personalizados','spark','Personalizados'],['clientes','users','Clientes'],['estoque','box','Estoque'],['financeiro','wallet','Financeiro'],['fornecedores','leaf','Produção e marcas'],['empresa','mountain','Sobre a empresa']];
function shell(content,r){const title=nav.find(n=>n[0]===r)?.[2]||'Visão geral';return `<aside class="sidebar" id="sidebar"><a class="brand" href="#/visao-geral">${officialLogo('brand-logo')}<div class="brand-name">encantos<br>da serra<small>EMPÓRIO DELIVERY</small></div></a><div class="nav-caption">ESPAÇO DE TRABALHO</div><nav aria-label="Menu principal">${nav.map(([id,ico,label])=>`<a class="nav-item ${id===r?'active':''}" href="#/${id}">${icon(ico)}${label}${id==='pedidos'?`<span class="nav-count">${getOrders().filter(o=>!['concluido','cancelado'].includes(o.status)).length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="nav-item" href="#/apresentacao">${icon('play')}Modo apresentação</a><button class="nav-item" data-action="reset" style="border:0;background:transparent;width:100%">${icon('refresh')}Reiniciar demonstração</button><div class="user"><div class="avatar">G4</div><div><strong>Equipe Encantos</strong><small>Ambiente demonstrativo</small></div></div></div></aside><main class="main"><header class="topbar"><div class="actions"><button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><div class="breadcrumb">Meu negócio <span>/ &nbsp; ${title}</span></div></div><div class="top-actions"><span class="demo-label"><i class="dot"></i>Protótipo · operação simulada</span><span class="top-date">Terça-feira, 03 de novembro</span><button class="icon-button" data-action="alerts" aria-label="Ver alertas de estoque">${icon('bell')}</button></div></header><div class="content">${content}<footer class="page-footer"><span>Feito para cuidar de quem produz e de quem compra.</span><span>Projeto acadêmico · Engenharia da Computação</span></footer></div></main>`;}
function orderRows(orders){return orders.map(o=>{const c=customer(o.customerId);return `<tr><td><button class="text-link" data-action="order" data-id="${o.id}">${o.id}</button></td><td><div class="customer-cell"><div class="avatar">${initials(c.name)}</div><div><strong>${esc(c.name)}</strong><span class="cell-muted">${c.type}</span></div></div></td><td>${esc(o.channel)}</td><td>${badge(o.status)}</td><td class="money">${money(E.total(o))}</td><td>${short(o.delivery)}</td></tr>`;}).join('');}
function dashboard(){const active=getOrders().filter(o=>o.status!=='concluido'),open=state.receivables.filter(r=>E.balance(r)>0),blocked=state.lots.filter(l=>E.days(l.expiry)<=7&&l.qty>0),low=state.products.filter(p=>E.stock(state,p.id,true)<p.minimum),todayTotal=state.orders.filter(o=>o.completedAt===E.TODAY).reduce((a,o)=>a+E.total(o),0);const stageTotals=['novo','analise','separacao','pronto','concluido'].map(s=>getOrders().filter(o=>o.status===s).reduce((a,o)=>a+E.total(o),0));const max=Math.max(...stageTotals,1);
return pageHeading('O CUIDADO COMEÇA POR AQUI','Um bom dia para encantar.','Acompanhe os pedidos e o que merece sua atenção hoje.',button('Formulário do cliente','public','link','')+button('Novo pedido','new-order'))+
`${officialBanner()}<div class="metrics">${metric('Pedidos em andamento',active.length,`${active.filter(o=>o.status==='novo').length} novos pedidos aguardando atendimento`,'board')}${metric('Concluído hoje',money(todayTotal),'Valor dos pedidos concluídos nesta demo','chart')}${metric('A receber',money(open.reduce((a,r)=>a+E.balance(r),0)),`<b>${open.filter(r=>E.days(r.due)<0).length} conta vencida</b> · controle de vendas a prazo`,'wallet')}${metric('Atenção ao estoque',blocked.length+low.length,`${blocked.length} lote bloqueado · ${low.length} produto abaixo do mínimo`,'box')}</div>
<div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>Pedidos por etapa</h2><p class="subtitle">Valor total dos pedidos em cada etapa da demonstração</p></div><span class="badge gray">Posição atual</span></div><div class="chart">${stageTotals.map((v,i)=>`<div class="chart-col"><b>${money(v)}</b><div class="bar ${i===4?'dark':''}" style="height:${Math.max(5,v/max*112)}px"></div><small>${['Novos','Em análise','Separação','Prontos','Concluídos'][i]}</small></div>`).join('')}</div><div class="chart-legend"><span><i class="legend-square"></i>Em atendimento</span><span><i class="legend-square dark"></i>Concluídos</span></div></section><section class="panel"><div class="panel-head"><h2>Pedidos recentes</h2><button class="text-link" data-action="navigate" data-route="pedidos">Ver todos ${icon('arrow')}</button></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Origem</th><th>Etapa</th><th>Valor</th><th>Entrega</th></tr></thead><tbody>${orderRows(getOrders().slice(0,5))}</tbody></table></div></section></div><div><section class="panel"><div class="panel-head"><h2>Precisam de atenção</h2><span class="badge amber">${blocked.length+low.length+open.filter(r=>E.days(r.due)<0).length}</span></div>${blocked.map(l=>`<div class="alert-row"><div class="alert-symbol red">${icon('alert')}</div><div><strong>Lote próximo do vencimento</strong><p>${product(l.productId).name} · ${l.code}<br>Vence em ${short(l.expiry)} · ${l.qty} unidades bloqueadas</p><button class="text-link" data-action="navigate" data-route="estoque">Conferir lote ${icon('arrow')}</button></div></div>`).join('')}${low.map(p=>`<div class="alert-row"><div class="alert-symbol">${icon('box')}</div><div><strong>Hora de repor ${esc(p.name.toLowerCase())}</strong><p>${E.stock(state,p.id,true)} disponíveis · mínimo de ${p.minimum}</p><button class="text-link" data-action="stock-entry" data-id="${p.id}">Registrar entrada ${icon('arrow')}</button></div></div>`).join('')}<div class="alert-row"><div class="alert-symbol green">${icon('wallet')}</div><div><strong>Vendas a prazo em acompanhamento</strong><p>${open.length} contas abertas · consulte as datas combinadas.</p><button class="text-link" data-action="navigate" data-route="financeiro">Ver recebimentos ${icon('arrow')}</button></div></div></section><section class="panel"><div class="panel-head"><h2>Últimas atividades</h2>${icon('clock')}</div><div class="activity">${state.activity.slice(0,4).map(a=>`<div class="activity-item"><i class="activity-point"></i><div><p>${esc(a.title)}</p><small>${esc(a.detail)}</small></div></div>`).join('')}</div></section></div></div><div class="welcome-banner"><div><strong>O próximo pedido pode começar em uma conversa.</strong><p>Compartilhe o formulário no WhatsApp ou Instagram e receba cada solicitação no quadro.</p></div><button class="btn" data-action="public">${icon('link')}Ver formulário do cliente</button></div>`;}
function card(o){const c=customer(o.customerId);return `<button class="ticket" data-action="order" data-id="${o.id}"><div class="ticket-top"><span class="ticket-id">${o.id}</span><span class="ticket-channel">${esc(o.channel)}</span></div><h3>${esc(c.name)}</h3><span class="badge ${c.type==='B2B'?'amber':'gray'}">${c.type==='B2B'?'Cliente comercial':'Varejo'}</span>${o.kind==='personalizado'?`<p class="ticket-custom">✧ Pedido personalizado${!o.approved?' · orçamento pendente':''}</p>`:''}<p class="summary">${o.items.slice(0,2).map(i=>`${i.qty}× ${esc(product(i.productId).name)}`).join('<br>')}${o.items.length>2?`<br>+ ${o.items.length-2} produto`:''}</p><div class="ticket-footer"><span>${short(o.delivery)}${o.payment==='fiado'?' · a prazo':''}</span><strong>${money(E.total(o))}</strong></div></button>`;}
function board(custom=false){let list=getOrders(custom?'personalizado':undefined);if(filter==='b2b')list=list.filter(o=>customer(o.customerId).type==='B2B');if(filter==='whatsapp')list=list.filter(o=>o.channel==='WhatsApp');if(query)list=list.filter(o=>(customer(o.customerId).name+' '+o.id).toLowerCase().includes(query.toLowerCase()));return pageHeading('CENTRAL DE ATENDIMENTO',custom?'Pedidos com um toque especial':'Cada pedido, no seu tempo.',custom?'Orçamentos, detalhes e aprovação reunidos em um só lugar.':'Organize o atendimento desde a primeira conversa até a entrega.',button('Formulário do cliente','public','link','')+button('Novo pedido','new-order'))+`<div class="toolbar"><div class="tabs" role="group" aria-label="Filtros de pedidos">${[['todos',custom?'Personalizados':'Todos os pedidos'],['b2b','Clientes B2B'],['whatsapp','WhatsApp']].map(([f,t])=>`<button class="tab ${filter===f?'active':''}" data-action="filter" data-filter="${f}">${t}</button>`).join('')}</div><label class="search">${icon('search')}<span class="screen-reader">Buscar pedido ou cliente</span><input id="order-search" placeholder="Buscar pedido ou cliente" value="${esc(query)}"></label></div><div class="board">${['novo','analise','separacao','pronto','concluido'].map(s=>`<section class="column"><div class="column-head">${statuses[s][0]}<small>${list.filter(o=>o.status===s).length}</small></div>${list.filter(o=>o.status===s).map(card).join('')||'<div class="empty">Tudo em dia por aqui.<br>Os pedidos desta etapa aparecerão aqui.</div>'}</section>`).join('')}</div><div class="note">${icon('message')} Abra um cartão para consultar detalhes e avançar o atendimento. Ao concluir, o sistema atualiza os lotes liberados e registra o financeiro. Os valores dos pedidos de exemplo são simulados; novos pedidos usam os preços consultados no catálogo oficial.</div>`;}
function inventory(){return pageHeading('RASTREABILIDADE E CUIDADO','Estoque com origem e validade.','Lotes, disponibilidade e conservação dos produtos artesanais.',button('Registrar entrada','stock-entry'))+`<div class="metrics">${metric('Unidades em estoque',state.lots.reduce((a,l)=>a+l.qty,0),'Saldo físico da demonstração','box')}${metric('Liberadas para pedidos',state.lots.filter(l=>E.days(l.expiry)>7).reduce((a,l)=>a+l.qty,0),'Validade acima da margem de 7 dias','check')}${metric('Lotes em atenção',state.lots.filter(l=>E.days(l.expiry)>7&&E.days(l.expiry)<=15&&l.qty>0).length,'Vencimento entre 8 e 15 dias','clock')}${metric('Lotes bloqueados',state.lots.filter(l=>E.days(l.expiry)<=7&&l.qty>0).length,'Vencimento em até 7 dias ou expirado','alert')}</div><section class="panel"><div class="panel-head"><h2>Inventário por lote</h2><span class="badge gray">FEFO · menor validade primeiro</span></div><div class="table-wrap"><table><thead><tr><th>Produto / produtor</th><th>Lote</th><th>Validade</th><th>Saldo</th><th>Situação online</th><th>Localização</th><th>Ação</th></tr></thead><tbody>${state.lots.map(l=>{const p=product(l.productId),d=E.days(l.expiry);return `<tr><td><div class="customer-cell">${officialProductThumb(p)}<div><strong class="product-label">${esc(p.name)}</strong><span class="cell-muted">${esc(p.producer)}</span></div></div></td><td>${esc(l.code)}</td><td>${l.expiry?date(l.expiry):'Indeterminada'}<span class="cell-muted">${l.expiry?(d<0?'Vencido':d+' dias restantes'):'Conforme descrição do produto'}</span></td><td><strong>${l.qty}</strong> ${p.unit}</td><td><span class="badge ${d<=7?'red':d<=15?'amber':'green'}">${d<=7?'Bloqueado':d<=15?'Atenção':'Liberado'}</span></td><td>${esc(l.location)}</td><td><button class="text-link" data-action="loss" data-id="${l.id}" ${!l.qty?'disabled':''}>Registrar perda</button></td></tr>`;}).join('')}</tbody></table></div></section><div class="note amber">A data de referência desta demonstração é 03/11/2026. Os pedidos online usam lotes com mais de 7 dias de validade. O saldo físico inclui os lotes bloqueados. A baixa ocorre uma única vez, na conclusão do pedido.</div>${state.movements.length?`<section class="panel"><div class="panel-head"><h2>Movimentações nesta sessão</h2></div><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Produto</th><th>Quantidade</th><th>Referência</th><th>Data</th></tr></thead><tbody>${state.movements.slice().reverse().slice(0,15).map(m=>`<tr><td>${m.type==='venda'?'Saída por venda':m.type==='entrada'?'Entrada':'Perda'}</td><td>${esc(product(m.productId).name)}</td><td>${m.qty}</td><td>${esc(m.orderId||m.reason||'Recebimento')}</td><td>${date(m.date)}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function finance(){const open=state.receivables.filter(r=>E.balance(r)>0),late=open.filter(r=>E.days(r.due)<0),paid=state.receivables.reduce((a,r)=>a+r.payments.reduce((n,p)=>n+p.amount,0),0);let rows=state.receivables;if(financeFilter==='abertas')rows=open;if(financeFilter==='vencidas')rows=late;if(financeFilter==='quitadas')rows=rows.filter(r=>E.balance(r)===0);return pageHeading('FINANCEIRO','Quem compra agora, paga depois.','Controle os valores em aberto e as datas combinadas com cada cliente.')+`<div class="metrics">${metric('Total a receber',money(open.reduce((a,r)=>a+E.balance(r),0)),`${open.length} contas em aberto`,'wallet')}${metric('Em atraso',money(late.reduce((a,r)=>a+E.balance(r),0)),`${late.length} conta com vencimento anterior a hoje`,'alert')}${metric('Recebimentos registrados',money(paid),'Acumulado dos dados desta demonstração','check')}${metric('Clientes com saldo aberto',new Set(open.map(r=>r.customerId)).size,'Histórico por cliente e por pedido','users')}</div><div class="toolbar"><div class="tabs" aria-label="Filtrar contas">${[['abertas','Em aberto'],['vencidas','Vencidas'],['quitadas','Quitadas'],['todas','Todas']].map(([v,t])=>`<button class="tab ${financeFilter===v?'active':''}" data-action="finance-filter" data-filter="${v}">${t}</button>`).join('')}</div><span class="micro">Referência: 03/11/2026</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Cliente / pedido</th><th>Venda</th><th>Vencimento</th><th>Recebido</th><th>Em aberto</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${rows.map(r=>{const c=customer(r.customerId),b=E.balance(r),isLate=b>0&&E.days(r.due)<0;return `<tr><td><strong>${esc(c.name)}</strong><button class="text-link cell-muted" data-action="order" data-id="${r.orderId}">${r.orderId}</button></td><td>${money(r.total)}</td><td>${date(r.due)}</td><td>${money(r.total-b)}</td><td><strong>${money(b)}</strong></td><td><span class="badge ${b===0?'green':isLate?'red':'amber'}">${b===0?'Quitado':isLate?'Vencido':'A vencer'}</span></td><td><button class="text-link" data-action="payment" data-id="${r.id}">${b===0?'Ver histórico':'Registrar recebimento'}</button></td></tr>`;}).join('')||'<tr><td colspan="7"><div class="empty">Nenhuma conta nesta situação.</div></td></tr>'}</tbody></table></div></section><div class="note">Os recebimentos podem ser parciais. Concluir uma venda a prazo cria uma conta com vencimento, sem marcar o pagamento. Clientes, vendas e recebimentos são simulações do projeto. O protótipo demonstra contas a receber e não calcula DRE contábil.</div>`;}
function clients(){return pageHeading('RELACIONAMENTO','Cada cliente tem uma história.','Clientes de varejo e comerciais, com origem do contato e histórico de pedidos.',button('Cadastrar cliente','new-client'))+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Perfil</th><th>Origem</th><th>Cidade</th><th>Pedidos</th><th>Saldo aberto</th><th>Histórico</th></tr></thead><tbody>${state.customers.map(c=>`<tr><td><div class="customer-cell"><div class="avatar">${esc(initials(c.name))}</div><div><strong>${esc(c.name)}</strong><span class="cell-muted">${esc(c.contact)}</span></div></div></td><td><span class="badge ${c.type==='B2B'?'amber':'green'}">${c.type}</span></td><td>${esc(c.channel)}</td><td>${esc(c.city||'A informar')}</td><td>${state.orders.filter(o=>o.customerId===c.id).length}</td><td>${money(state.receivables.filter(r=>r.customerId===c.id).reduce((a,r)=>a+E.balance(r),0))}</td><td><button class="text-link" data-action="client" data-id="${c.id}">Ver cliente ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div></section><div class="note">Os cadastros de exemplo são fictícios. No sistema definitivo, os perfis B2C/B2B também terão documento, endereços e tabela comercial vinculada.</div>`;}
const producers=[{name:'Família Oliveira',place:'Serra do Cipó, MG',category:'Queijos artesanais',capacity:180,used:124,cert:'Certificação a validar'}, {name:'Sítio das Flores',place:'Santana do Riacho, MG',category:'Doces e geleias',capacity:250,used:170,cert:'Certificação a validar'}, {name:'Alambique do Vale',place:'Jaboticatubas, MG',category:'Cachaças artesanais',capacity:120,used:60,cert:'Certificação a validar'}, {name:'Família Martins',place:'Conceição do Mato Dentro, MG',category:'Embutidos artesanais',capacity:150,used:95,cert:'Certificação a validar'}];
function suppliers(){return pageHeading('QUEM FAZ ACONTECER','A origem de cada encanto.','Famílias produtoras e capacidade artesanal. Valores ilustrativos para validação.')+`<div class="producer-grid">${producers.map(p=>`<section class="producer"><div class="producer-top"><div class="avatar">${initials(p.name)}</div><div><h3>${p.name}</h3><p class="subtitle">${p.place}</p></div></div><span class="badge green">${p.category}</span><div class="progress"><span style="width:${p.used/p.capacity*100}%"></span></div><div class="micro">Capacidade comprometida: ${p.used} de ${p.capacity} un/mês</div><div class="note" style="margin-bottom:0">${p.cert}</div></section>`).join('')}</div><div class="note amber">Visão conceitual do módulo de compras do DER. Emissão de ordens de compra, certificações e tolerância de peso de 5% fazem parte da próxima etapa.</div>`;}
function openModal(content){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1">${content}</section></div>`;document.body.style.overflow='hidden';$('.modal').focus();}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus?.();}
function modalHead(eyebrow,title){return `<div class="modal-header"><div><span class="eyebrow">${eyebrow}</span><h2 id="dialog-title">${title}</h2></div><button class="icon-button" data-action="close" aria-label="Fechar">${icon('close')}</button></div>`;}
function orderDetail(id){const o=state.orders.find(o=>o.id===id),c=customer(o.customerId),statusKeys=['novo','analise','separacao','pronto','concluido'];let allocations=[],planError='';if(!['concluido','cancelado'].includes(o.status))try{allocations=E.plan(state,o);}catch(e){planError=e.message;}else allocations=o.allocations||[];
openModal(modalHead(o.id,esc(c.name))+`<div class="actions">${badge(o.status)}<span class="badge gray">${o.channel}</span><span class="badge amber">Pedido simulado</span>${o.kind==='personalizado'?'<span class="badge purple">Personalizado</span>':''}</div><div class="modal-section details-grid"><div><span class="field-label">Entrega desejada</span><div class="field-value">${date(o.delivery)}</div></div><div><span class="field-label">Pagamento</span><div class="field-value">${o.payment==='fiado'?'A prazo · vence '+date(o.due):o.payment==='pix'?'Pix':'Cartão'}</div></div><div style="grid-column:1/-1"><span class="field-label">Observações do cliente</span><div class="field-value">${esc(o.notes||'Sem observações.')}</div></div></div>${o.custom?`<div class="note"><strong>Pedido personalizado</strong><br>${esc(o.custom)}<br>${o.approved?'Orçamento aprovado para a demonstração.':'Aguardando aprovação do orçamento pelo cliente.'}</div>`:''}<div class="modal-section"><h3>Produtos solicitados</h3><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Qtd.</th><th>Subtotal</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(product(i.productId).name)}</td><td>${i.qty}</td><td>${money(i.qty*i.price)}</td></tr>`).join('')}</tbody></table></div><div class="form-total"><span>Total do pedido</span><strong>${money(E.total(o))}</strong></div></div><div class="modal-section"><h3>Separação e embalagem</h3>${planError?`<div class="note red">${esc(planError)}</div>`:allocations.length?allocations.map(a=>{const l=state.lots.find(l=>l.id===a.lotId),p=product(a.productId);return `<div class="note"><strong>${a.qty}× ${p.name} · ${esc(l.code)}</strong><br>${esc(l.location)} · ${l.expiry?'vence '+date(l.expiry):'validade indeterminada'}<br>${p.packing}</div>`;}).join(''):'<p class="subtitle" style="margin-top:12px">Pedido histórico. A composição da baixa anterior não integra os dados de exemplo.</p>'}</div><div class="modal-footer">${!['concluido','cancelado'].includes(o.status)?`<button class="btn danger" data-action="cancel-order" data-id="${id}">Cancelar pedido</button>`:''}${o.kind==='personalizado'&&!o.approved&&!['concluido','cancelado'].includes(o.status)?`<button class="btn primary" data-action="approve" data-id="${id}">Registrar aprovação do orçamento</button>`:''}${!['concluido','cancelado'].includes(o.status)&&!(o.kind==='personalizado'&&!o.approved)?`<button class="btn primary" data-action="advance" data-id="${id}" ${planError&&o.status==='pronto'?'disabled':''}>${o.status==='pronto'?'Concluir pedido':`Avançar: ${statuses[statusKeys[statusKeys.indexOf(o.status)+1]][0]}`}${icon('arrow')}</button>`:''}</div>${o.status==='pronto'?'<p class="hint" style="color:#879475;margin-top:15px">A conclusão confirma a entrega, realiza a baixa dos lotes e registra o financeiro.</p>':''}`);}
function stockModal(pid){openModal(modalHead('RECEBIMENTO','Nova entrada de estoque')+`<form id="stock-form"><div class="form-grid"><label class="wide">Produto<select name="productId">${state.products.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${p.name}</option>`).join('')}</select></label><label>Código do lote<input name="code" required maxlength="40" placeholder="Ex.: QMC-1103"></label><label>Quantidade<input name="qty" type="number" required min="1" max="99999" step="1"></label><label>Fabricação<input type="date" name="manufactured" required max="${E.TODAY}"></label><label>Validade (deixe em branco se indeterminada)<input type="date" name="expiry" min="${E.TODAY}"></label><label>Custo unitário (R$)<input name="cost" type="number" required min="0.01" step="0.01"></label><label>Localização<input name="location" required maxlength="80" placeholder="Câmara / prateleira"></label></div><div class="form-error" role="alert"></div><div class="modal-footer"><button class="btn" type="button" data-action="close">Voltar</button><button class="btn primary" type="submit">Registrar entrada</button></div></form>`);}
function lossModal(id){const l=state.lots.find(l=>l.id===id);openModal(modalHead('CONTROLE DE PERDAS',esc(l.code))+`<p class="subtitle">${product(l.productId).name} · saldo de ${l.qty} unidades</p><form id="loss-form" data-id="${id}"><div class="form-grid" style="margin-top:25px"><label>Quantidade perdida<input name="qty" type="number" min="1" max="${l.qty}" required step="1"></label><label>Motivo<select name="reason"><option>Avaria</option><option>Transporte</option><option>Expiração</option><option>Deterioração</option></select></label><label class="wide">Justificativa<textarea name="notes" required maxlength="500"></textarea></label></div><div class="form-error" role="alert"></div><div class="modal-footer"><button class="btn primary" type="submit">Registrar perda</button></div></form>`);}
function paymentModal(id){const r=state.receivables.find(r=>r.id===id),b=E.balance(r);openModal(modalHead('RECEBIMENTOS',esc(customer(r.customerId).name))+`<p class="subtitle">${r.orderId} · vencimento em ${date(r.due)}</p><div class="form-total"><span>Saldo em aberto</span><strong>${money(b)}</strong></div>${b>0?`<form id="payment-form" data-id="${id}"><div class="form-grid"><label>Valor recebido (R$)<input name="amount" type="number" min="0.01" max="${b}" step="0.01" value="${b}" required></label><label>Forma de recebimento<select name="method"><option value="pix">Pix</option><option value="dinheiro">Dinheiro</option><option value="cartao">Cartão</option></select></label></div><div class="form-error" role="alert"></div><div class="modal-footer"><button class="btn primary" type="submit">Confirmar recebimento</button></div></form>`:''}<div class="modal-section"><h3>Histórico de pagamentos</h3>${r.payments.length?`<table><tbody>${r.payments.map(p=>`<tr><td>${date(p.date)}</td><td>${p.method}</td><td>${money(p.amount)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Nenhum pagamento registrado.</div>'}</div>`);}
function clientModal(id){const c=customer(id),orders=state.orders.filter(o=>o.customerId===id);openModal(modalHead('HISTÓRICO DO CLIENTE',esc(c.name))+`<div class="details-grid"><div><span class="field-label">Perfil e origem</span><div class="field-value">${c.type} · ${esc(c.channel)}</div></div><div><span class="field-label">Cidade</span><div class="field-value">${esc(c.city||'A informar')}</div></div><div><span class="field-label">Contato</span><div class="field-value">${esc(c.contact)}</div></div></div><div class="modal-section"><h3>Pedidos anteriores</h3>${orders.length?orders.map(o=>`<div class="note"><div class="actions" style="justify-content:space-between"><strong>${o.id} · ${money(E.total(o))}</strong>${badge(o.status)}</div><p>${o.items.map(i=>`${i.qty}× ${esc(product(i.productId).name)}`).join(', ')}</p><div class="actions"><button class="text-link" data-action="order" data-id="${o.id}">Ver pedido ${icon('arrow')}</button>${c.type==='B2B'?`<button class="btn" data-action="reorder" data-id="${o.id}">Solicitar recompra</button>`:''}</div></div>`).join(''):'<div class="empty">Este cliente ainda não tem pedidos.</div>'}</div>`);}
function newClient(){openModal(modalHead('RELACIONAMENTO','Novo cliente')+`<form id="client-form"><div class="form-grid"><label class="wide">Nome ou razão social<input name="name" required maxlength="100"></label><label>Perfil<select name="type"><option>B2C</option><option>B2B</option></select></label><label>Origem<select name="channel"><option>WhatsApp</option><option>Instagram</option><option>Formulário</option></select></label><label class="wide">Contato<input name="contact" required maxlength="100" placeholder="Telefone ou e-mail de demonstração"></label><label class="wide">Cidade e UF<input name="city" maxlength="100"></label></div><div class="form-error" role="alert"></div><div class="modal-footer"><button class="btn primary">Cadastrar cliente</button></div></form>`);}
function publicPage(){let origin=new URLSearchParams(location.hash.split('?')[1]||'').get('origem')||'WhatsApp';if(!['WhatsApp','Instagram','Formulário'].includes(origin))origin='WhatsApp';return `<main class="public"><header class="public-header"><a class="public-brand" href="#/visao-geral">${officialLogo('public-logo')}<span>encantos da serra<small>Empório delivery</small></span></a><a class="text-link" href="#/pedidos">Área da equipe ${icon('arrow')}</a></header><div class="public-content"><div class="eyebrow">DA NOSSA SERRA PARA VOCÊ</div><h1>O seu próximo encanto<br>começa aqui.</h1><p class="subtitle">Escolha seus produtos ou conte a sua ideia. Nossa equipe recebe a solicitação<br>e combina os detalhes com você pelo canal de origem.</p><div class="note">Protótipo acadêmico com catálogo do site oficial, consultado em 03/11/2026. Use dados de cliente fictícios. O envio cria um ticket neste navegador e não envia pedido à empresa.</div><form id="order-form" class="public-form"><div class="form-grid"><label class="wide">Seu nome ou nome da empresa<input name="name" required maxlength="100" placeholder="Como podemos chamar você?"></label><label>Contato para retorno<input name="contact" required maxlength="100" placeholder="Telefone ou e-mail de exemplo"></label><label>Você compra para<select name="type"><option value="B2C">Consumo ou presente</option><option value="B2B">Meu negócio</option></select></label><label>Como chegou até nós?<select name="channel">${['WhatsApp','Instagram','Formulário'].map(c=>`<option ${origin===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Data desejada<input type="date" name="delivery" min="${E.TODAY}" required></label><label class="wide">Tipo de pedido<select name="kind" id="kind-select"><option value="padrao">Produtos do catálogo</option><option value="personalizado">Pedido personalizado</option></select></label></div><div class="modal-section"><h3 style="margin-bottom:18px">O que vai no seu pedido?</h3><div id="form-items">${itemRow()}</div><button type="button" class="text-link" data-action="add-item">${icon('plus')} Adicionar outro produto</button></div><div class="form-grid" style="margin-top:24px"><label class="wide" id="custom-field" hidden>Conte a sua ideia<textarea name="custom" maxlength="1000" placeholder="Cesta, ocasião, embalagem, cartão e outros detalhes"></textarea></label><label>Forma de pagamento<select name="payment" id="payment-select"><option value="pix">Pix</option><option value="cartao">Cartão</option><option value="fiado">A prazo, sujeito a aprovação</option></select></label><label id="due-field" hidden>Data combinada para pagamento<input type="date" name="due" min="${E.TODAY}"></label><label class="wide">Outras informações<textarea name="notes" maxlength="1000" placeholder="Detalhes da entrega ou algum cuidado especial?"></textarea></label></div><div class="form-total"><span id="total-label">Total dos produtos</span><strong id="form-total">${money(state.products[0].price)}</strong></div><p class="subtitle">Preços públicos consultados em 03/11/2026, sujeitos a alteração na loja. Frete, disponibilidade e personalizações dependem da empresa. Fiado e Pix são opções simuladas do projeto. O envio não gera uma compra.</p><div class="form-error" role="alert"></div><button class="btn primary" style="width:100%;margin-top:22px;padding:14px" type="submit">Enviar solicitação ${icon('arrow')}</button></form><p class="hint" style="color:#909d80;text-align:center;margin-top:25px">Protótipo Encantos da Serra · Nenhuma mensagem é enviada ao WhatsApp ou Instagram.</p></div></main>`;}
function itemRow(){const selected=new URLSearchParams(location.hash.split('?')[1]||'').get('produto');return `<div class="form-item"><label>Produto<select name="productId">${state.products.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${money(p.price)}</option>`).join('')}</select></label><label>Qtd.<input name="qty" type="number" min="1" max="9999" value="1" required step="1"></label><button type="button" class="icon-button" data-action="remove-item" aria-label="Remover produto">${icon('close')}</button></div>`;}
function updateForm(){if(!$('#order-form'))return;const custom=$('#kind-select').value==='personalizado',fiado=$('#payment-select').value==='fiado';$('#custom-field').hidden=!custom;$('#custom-field textarea').required=custom;$('#due-field').hidden=!fiado;$('#due-field input').required=fiado;$('#form-total').textContent=money([...document.querySelectorAll('.form-item')].reduce((a,row)=>a+product(row.querySelector('select').value).price*(Number(row.querySelector('input').value)||0),0));$('#total-label').textContent=custom?'Produtos · orçamento a confirmar':'Total dos produtos';}
const slides=[
  {title:'Encantos da Serra',sub:'Empório delivery com iguarias, queijos, doces e biscoitos associados à Serra da Canastra.',detail:'Protótipo de validação · Grupo G4 · Novembro de 2026'},
  {title:'O empório no projeto',sub:'O site oficial apresenta um catálogo com 11 categorias. Esta demonstração reúne 13 produtos com fotos e preços consultados em 03/11/2026.',list:['Identidade e contatos preservados conforme publicados.','Cada produto tem link para a página oficial.','Clientes, pedidos, estoque e financeiro são simulações acadêmicas.'],detail:'Fontes e divergências estão na área Sobre a empresa.'},
  {title:'O atendimento precisa de continuidade',sub:'O cliente conversa pelo WhatsApp ou Instagram. A equipe precisa reunir o pedido, acompanhar a entrega e saber o que falta receber.',list:['Uma solicitação vira um ticket identificável.','Cada etapa mantém os detalhes do pedido.','Estoque e financeiro acompanham a conclusão.']},
  {title:'O caminho do pedido',sub:'Contato no WhatsApp ou Instagram, link do formulário, ticket no quadro, separação, conclusão e recebimento.',list:['O formulário preserva a origem do contato.','A equipe confirma orçamento e condições.','A conclusão dá baixa no estoque uma única vez.']},
  {title:'Uma central para a operação',sub:'O painel reúne pedidos, alertas de validade e valores a receber. O quadro mostra novos pedidos, análise, separação, prontos e concluídos.',list:['Detalhes do cliente e dos produtos em cada cartão.','Histórico de atendimento e previsão de entrega.']},
  {title:'Personalizados têm aprovação própria',sub:'Uma visão dedicada reúne cestas, kits e embalagens especiais. Os produtos do catálogo compõem a base do orçamento.',list:['A equipe registra os detalhes da solicitação.','Aprovação do orçamento libera o avanço.','Frete e personalizações precisam de validação comercial.']},
  {title:'O estoque respeita a validade',sub:'Os lotes registram origem, saldo e localização. A separação usa primeiro a menor validade entre os lotes liberados.',list:['Até 15 dias: atenção ao vencimento.','Até 7 dias: bloqueio para pedidos online.','A conclusão baixa os lotes e registra as movimentações.'],detail:'O DER chama essa regra de PEPS/FIFO. A seleção por vencimento corresponde a FEFO, sujeito à validação da equipe.'},
  {title:'O fiado tem data e saldo',sub:'O financeiro mostra quem comprou, quanto falta pagar e qual foi a data combinada.',list:['A venda a prazo gera uma conta a receber.','Pagamentos parciais reduzem o saldo.','Contas vencidas ficam em uma visão própria.']},
  {title:'Uma base de dados conectada',sub:'Cliente e pedido ligam o atendimento ao estoque e ao financeiro.',list:['Clientes, canais, endereços, pedidos e itens.','Produtos, produtores, lotes e movimentações.','Contas a receber e pagamentos separados.'],detail:'O modelo também prevê compras, preços B2B e expedição para evolução posterior.'},
  {title:'Demonstração e próximos passos',sub:'O protótipo simula o fluxo no navegador, com dados fictícios e sem integração real com mensageiros.',list:['Validar etapas, aprovação de fiado e regras B2B.','Confirmar FEFO, limite de validade e personalizações.','Implementar autenticação, banco e integração oficial.'],detail:'Critério do MVP: um pedido rastreável até a entrega, com baixa consistente e saldo financeiro correto.'},
  {title:'Validação com os responsáveis',sub:'A demonstração permite discutir a rotina antes de investir na implementação completa.',list:['O formulário reúne os dados necessários?','As etapas refletem o trabalho da equipe?','Quem aprova orçamento e venda a prazo?','Quais regras são indispensáveis à primeira entrega?']}
];
function presentation(){const s=slides[currentSlide];return `<main class="slides-page"><div class="slide-count">ENCANTOS DA SERRA &nbsp; / &nbsp; ${String(currentSlide+1).padStart(2,'0')} DE ${slides.length}</div><div class="slide-frame"><h1>${s.title}</h1><p>${s.sub}</p>${s.list?`<ul class="slide-list">${s.list.map(t=>`<li>${t}</li>`).join('')}</ul>`:''}${s.detail?`<p class="slide-detail">${s.detail}</p>`:''}</div><div class="slides-controls"><a class="btn" href="#/visao-geral">Abrir demonstração ${icon('arrow')}</a><span class="hint">Use as setas do teclado para navegar</span><div class="actions"><button class="btn" data-action="slide-prev" ${currentSlide===0?'disabled':''}>Anterior</button><button class="btn" data-action="slide-next" ${currentSlide===slides.length-1?'disabled':''}>Próximo ${icon('arrow')}</button></div></div></main>`;}
function render(){const r=route();if(r==='solicitar')$('#app').innerHTML=publicPage();else if(r==='apresentacao')$('#app').innerHTML=presentation();else $('#app').innerHTML=shell(({pedidos:()=>board(false),personalizados:()=>board(true),clientes:clients,estoque:inventory,financeiro:finance,fornecedores:officialSuppliersPage,catalogo:officialCatalogPage,empresa:officialCompanyPage}[r]||dashboard)(),r);document.title='Encantos da Serra · '+(r==='solicitar'?'Seu pedido':r==='apresentacao'?'Apresentação':nav.find(n=>n[0]===r)?.[2]||'Visão geral');if(r==='solicitar')updateForm();}
function nextId(){return 'ES-'+(Math.max(1048,...state.orders.map(o=>Number(o.id.split('-')[1])))+1);}
function formError(form,e){form.querySelector('.form-error').textContent=e.message;}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const {action:a,id}=b.dataset;try{
  if(a==='close')closeModal();
  if(a==='navigate'){closeModal();go(b.dataset.route);}
  if(a==='menu')$('#sidebar').classList.toggle('open');
  if(a==='alerts'){go('estoque');toast('Confira os lotes em atenção e bloqueados.');}
  if(a==='public'||a==='new-order')go('solicitar?origem=WhatsApp');
  if(a==='filter'){filter=b.dataset.filter;render();}
  if(a==='finance-filter'){financeFilter=b.dataset.filter;render();}
  if(a==='official-product')officialProductModal(id);
  if(a==='request-product'){closeModal();go('solicitar?origem=Formulário&produto='+encodeURIComponent(id));}
  if(a==='order')orderDetail(id);
  if(a==='stock-entry')stockModal(id);
  if(a==='loss')lossModal(id);
  if(a==='payment')paymentModal(id);
  if(a==='client')clientModal(id);
  if(a==='new-client')newClient();
  if(a==='approve'){const o=state.orders.find(o=>o.id===id);o.approved=true;save();render();orderDetail(id);toast('Aprovação do orçamento registrada.');}
  if(a==='advance'){let o=state.orders.find(o=>o.id===id);if(o.status==='pronto'){state=E.complete(state,id);save();closeModal();render();toast('Pedido concluído. Estoque e financeiro atualizados.');}else{if(o.kind==='personalizado'&&!o.approved)throw Error('Registre a aprovação do orçamento.');const stages=['novo','analise','separacao','pronto'];o.status=stages[stages.indexOf(o.status)+1];save();render();orderDetail(id);toast('Etapa atualizada.');}}
  if(a==='cancel-order'){const o=state.orders.find(o=>o.id===id);if(o.status==='concluido')throw Error('O estorno de pedidos concluídos pertence à próxima etapa.');openModal(modalHead('CANCELAMENTO',`Cancelar ${id}?`)+`<p class="subtitle">O pedido sairá do quadro ativo. Nenhum estoque foi baixado nesta etapa.</p><div class="modal-footer"><button class="btn" data-action="order" data-id="${id}">Voltar</button><button class="btn danger" data-action="confirm-cancel" data-id="${id}">Confirmar cancelamento</button></div>`);}
  if(a==='confirm-cancel'){state.orders.find(o=>o.id===id).status='cancelado';save();closeModal();render();toast('Pedido cancelado.');}
  if(a==='add-item'){$('#form-items').insertAdjacentHTML('beforeend',itemRow());updateForm();}
  if(a==='remove-item'){if(document.querySelectorAll('.form-item').length<=1)throw Error('Mantenha pelo menos um produto no pedido.');b.closest('.form-item').remove();updateForm();}
  if(a==='reorder'){const old=state.orders.find(o=>o.id===id);const n=E.clone(old);n.id=nextId();n.status='novo';n.date=E.TODAY;n.delivery='2026-11-10';n.due=n.payment==='fiado'?'2026-11-15':null;n.items=n.items.map(i=>({...i,price:product(i.productId).price}));delete n.completedAt;delete n.financeId;delete n.allocations;n.notes='Recompra de '+old.id+'. Confirmar prazo e condições com o cliente.';if(n.kind==='personalizado')n.approved=false;state.orders.unshift(n);save();closeModal();go('pedidos');render();toast('Recompra criada como novo pedido. Preços e condições sujeitos à confirmação.');}
  if(a==='reset')openModal(modalHead('DEMONSTRAÇÃO','Recomeçar a apresentação?')+'<p class="subtitle">Os pedidos e pagamentos criados neste navegador serão substituídos pelos exemplos iniciais.</p><div class="modal-footer"><button class="btn" data-action="close">Manter dados</button><button class="btn primary" data-action="confirm-reset">Reiniciar demonstração</button></div>');
  if(a==='confirm-reset'){state=E.seed();save();closeModal();render();toast('Demonstração reiniciada.');}
  if(a==='slide-prev'){currentSlide=Math.max(0,currentSlide-1);render();}
  if(a==='slide-next'){currentSlide=Math.min(slides.length-1,currentSlide+1);render();}
}catch(e){toast(e.message);}});
document.addEventListener('input',ev=>{if(ev.target.id==='catalog-search'){const at=ev.target.selectionStart;catalogSearch=ev.target.value;render();$('#catalog-search').focus();$('#catalog-search').setSelectionRange(at,at);}if(ev.target.id==='order-search'){const at=ev.target.selectionStart;query=ev.target.value;const active=route();$('#app').innerHTML=shell(board(active==='personalizados'),active);$('#order-search').focus();$('#order-search').setSelectionRange(at,at);}if(ev.target.closest('#order-form'))updateForm();});
document.addEventListener('change',ev=>{if(ev.target.id==='catalog-category'){catalogFilter=ev.target.value;render();}if(ev.target.closest('#order-form'))updateForm();});
document.addEventListener('submit',ev=>{const f=ev.target;if(!['order-form','stock-form','loss-form','payment-form','client-form'].includes(f.id))return;ev.preventDefault();const v=Object.fromEntries(new FormData(f));try{
  if(f.id==='order-form'){
    if(!v.name.trim()||!v.contact.trim())throw Error('Informe nome e contato.');if(!v.delivery||E.days(v.delivery)<0)throw Error('Escolha uma data válida para a entrega.');
    if(v.kind==='personalizado'&&!v.custom.trim())throw Error('Descreva a personalização desejada.');if(v.payment==='fiado'&&(!v.due||E.days(v.due)<0))throw Error('Informe a data de pagamento.');
    const items=[...f.querySelectorAll('.form-item')].map(row=>{const p=product(row.querySelector('select').value),qty=Number(row.querySelector('input').value);if(!Number.isInteger(qty)||qty<1||qty>9999)throw Error('Informe quantidades inteiras válidas.');return {productId:p.id,qty,price:p.price};});
    const cid='c-'+Date.now(),id=nextId();state.customers.push({id:cid,name:v.name.trim(),contact:v.contact.trim(),type:v.type,channel:v.channel,city:''});state.orders.unshift({id,customerId:cid,channel:v.channel,kind:v.kind,status:'novo',items,date:E.TODAY,delivery:v.delivery,payment:v.payment,due:v.payment==='fiado'?v.due:null,notes:v.notes.trim(),custom:v.kind==='personalizado'?v.custom.trim():'',approved:v.kind!=='personalizado'});state.activity.unshift({title:v.name.trim()+' enviou um pedido',detail:id+' · '+v.channel,date:E.TODAY});save();$('.public-content').innerHTML=`<div class="success">${icon('check')}<div class="eyebrow">SOLICITAÇÃO RECEBIDA</div><h2>Seu pedido já tem um lugar.</h2><p>O protocolo é <strong>${id}</strong>.<br>A equipe vai conferir os produtos e combinar os próximos passos.<br>${v.kind==='personalizado'?'Seu pedido personalizado aguarda orçamento.':''}</p><div class="actions" style="justify-content:center;margin-top:25px"><a class="btn primary" href="#/pedidos">Ver o ticket na central ${icon('arrow')}</a><button class="btn" data-action="public" onclick="render()">Nova solicitação</button></div><p class="hint" style="color:#909d80;margin-top:25px">Demonstração local. Nenhuma mensagem foi enviada.</p></div>`;window.scrollTo(0,0);
  }
  if(f.id==='stock-form'){const qty=Number(v.qty),cost=Number(v.cost);if(!Number.isInteger(qty)||qty<1||!Number.isFinite(cost)||cost<=0)throw Error('Confira quantidade e custo.');if(!v.expiry&&!product(v.productId).noExpiry)throw Error('Informe a validade deste produto.');if(v.expiry&&(v.manufactured>v.expiry||E.days(v.expiry)<0))throw Error('Confira as datas de fabricação e validade.');if(state.lots.some(l=>l.productId===v.productId&&l.code===v.code.trim()))throw Error('Este código de lote já existe para o produto.');if(!v.code.trim()||!v.location.trim())throw Error('Informe lote e localização.');const id='l-'+Date.now();state.lots.push({id,productId:v.productId,code:v.code.trim(),qty,expiry:v.expiry||null,manufactured:v.manufactured,received:E.TODAY,location:v.location.trim(),cost});state.movements.push({id:'m-'+Date.now(),type:'entrada',lotId:id,productId:v.productId,qty,date:E.TODAY});save();closeModal();render();toast('Entrada registrada com lote e validade.');}
  if(f.id==='loss-form'){const l=state.lots.find(l=>l.id===f.dataset.id),qty=Number(v.qty);if(!Number.isInteger(qty)||qty<1||qty>l.qty||!v.notes.trim())throw Error('Confira a quantidade e a justificativa.');l.qty-=qty;state.movements.push({id:'m-'+Date.now(),type:'perda',lotId:l.id,productId:l.productId,qty,reason:v.reason+': '+v.notes.trim(),date:E.TODAY});save();closeModal();render();toast('Perda registrada e saldo atualizado.');}
  if(f.id==='payment-form'){state=E.receive(state,f.dataset.id,v.amount,v.method);save();closeModal();render();toast('Recebimento registrado e saldo atualizado.');}
  if(f.id==='client-form'){if(!v.name.trim()||!v.contact.trim())throw Error('Informe nome e contato.');state.customers.push({id:'c-'+Date.now(),name:v.name.trim(),contact:v.contact.trim(),city:v.city.trim(),type:v.type,channel:v.channel});save();closeModal();render();toast('Cliente cadastrado.');}
}catch(e){formError(f,e);}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal();if($('.modal')&&ev.key==='Tab'){const list=[...$('.modal').querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled&&x.offsetParent!==null);if(list.length){const first=list[0],last=list.at(-1);if(ev.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}}if(route()==='apresentacao'){if(ev.key==='ArrowRight'){currentSlide=Math.min(slides.length-1,currentSlide+1);render();}if(ev.key==='ArrowLeft'){currentSlide=Math.max(0,currentSlide-1);render();}}});
window.addEventListener('hashchange',()=>{closeModal();query='';filter='todos';render();window.scrollTo(0,0);});
render();
